#!/bin/sh
# Build the release firmware and write one merged image for flashing new
# boards: bootloader, partition table and app at their offsets in a single
# .bin that is written at 0x0.
#
#   scripts/make_release.sh            -> dist/sand-physics-<version>.bin
#
# Offsets and flash settings are taken from the build's flasher_args.json
# (generated by ESP-IDF from sdkconfig), not hard-coded. Uses PlatformIO's
# Python and bundled esptool; set PLATFORMIO_CORE_DIR if PlatformIO is not in
# ~/.platformio.
set -eu

cd "$(dirname "$0")/.."
CORE="${PLATFORMIO_CORE_DIR:-$HOME/.platformio}"
PY="$CORE/penv/bin/python"
PIO="$CORE/penv/bin/pio"
ESPTOOL="$CORE/packages/tool-esptoolpy/esptool.py"
command -v pio >/dev/null 2>&1 && PIO="$(command -v pio)"

ENV=release
BUILD=".pio/build/$ENV"
VERSION="$(tr -d ' \r\n' < version.txt)"
OUT="dist/sand-physics-$VERSION.bin"

"$PIO" run -e "$ENV"

mkdir -p dist
# flasher_args.json names the files as ESP-IDF builds them; PlatformIO writes
# the same images as bootloader.bin, partitions.bin and firmware.bin.
ARGS="$("$PY" - "$BUILD" <<'EOF'
import json, sys
build = sys.argv[1]
d = json.load(open(build + "/flasher_args.json"))
fs = d["flash_settings"]
parts = []
for off, name in sorted(d["flash_files"].items(), key=lambda kv: int(kv[0], 16)):
    if "bootloader" in name:
        f = "bootloader.bin"
    elif "partition" in name:
        f = "partitions.bin"
    else:
        f = "firmware.bin"
    parts.append("%s %s/%s" % (off, build, f))
print("--chip %s merge_bin --flash_mode %s --flash_freq %s --flash_size %s %s" % (
    d["extra_esptool_args"]["chip"], fs["flash_mode"], fs["flash_freq"], fs["flash_size"], " ".join(parts)))
EOF
)"
# shellcheck disable=SC2086 # ARGS is a word list by design
"$PY" "$ESPTOOL" $ARGS -o "$OUT"

SIZE=$(wc -c < "$OUT" | tr -d ' ')
echo
echo "merged image: $OUT ($SIZE bytes)"
echo "  esptool $ARGS"
if command -v sha256sum >/dev/null 2>&1; then
    echo "  sha256 $(sha256sum "$OUT" | cut -d' ' -f1)"
fi
echo
echo "flash a new board (USB-C, port may differ):"
echo "  $PY $ESPTOOL --chip esp32s3 --port /dev/ttyACM0 write_flash 0x0 $OUT"
